// Package model wraps the Go standard-library AST into phpmd-style code
// artifacts (Class, Interface, Method, Function, Field, Parameter). Rules are
// written against these artifacts, mirroring how PHPMD rules operate on
// pdepend's ASTClass / ASTMethod / ASTFunction nodes.
package model

import (
	"go/ast"
	"go/token"
	"maps"
	"sync"

	"github.com/quality-gates/messgo/internal/metrics"
)

// NodeType identifies the kind of artifact, used for rule message rendering
// (the PHPMD "{0}" placeholder is typically the artifact type: "class",
// "method", "function", "interface").
type NodeType string

const (
	TypeClass     NodeType = "class"
	TypeInterface NodeType = "interface"
	TypeTrait     NodeType = "trait"
	TypeMethod    NodeType = "method"
	TypeFunction  NodeType = "function"
)

// MemberKey identifies a selected field or method by its owning named type.
// Type is normalized to the receiver/literal type name without a pointer.
type MemberKey struct {
	Type string
	Name string
}

// File is a parsed Go source file plus all artifacts discovered within it.
type File struct {
	Path       string
	Fset       *token.FileSet
	Syntax     *ast.File
	Src        []byte
	Package    string
	Classes    []*Class
	Interfaces []*Interface
	Functions  []*Function
	// AllFuncs includes both free functions and methods, in source order.
	AllFuncs []*Function

	PackageScope

	analysis fileAnalysisCache
}

// PackageScope holds package-wide artifacts and analysis data aggregated across
// all files in the package by the runner.
type PackageScope struct {
	// MutatedGlobals holds the package-level variable names that are mutated
	// anywhere in this file's package. It is populated by the runner once all
	// of a package's files are parsed, enabling cross-file analysis. It is nil
	// when a file is analyzed in isolation (rules then fall back to single-file
	// analysis).
	MutatedGlobals map[string]bool
	// PackageClasses holds all structs from every file in this file's package.
	// It is populated by the runner after parsing, enabling cross-file embedding
	// analysis. When nil (file analyzed in isolation), rules fall back to
	// this file's own Classes.
	PackageClasses []*Class
	// PackageInterfaces holds all interface types from every file in this
	// file's package. It is populated by the runner after parsing, enabling
	// cross-file interface-satisfaction analysis. When nil (file analyzed in
	// isolation), rules fall back to this file's own Interfaces.
	PackageInterfaces []*Interface
	// PackageFunctions holds all package-level free functions from every file
	// in this file's package. It is populated by the runner after parsing,
	// enabling cross-file call return-type resolution. When nil (file analyzed
	// in isolation), rules fall back to this file's own free functions.
	PackageFunctions []*Function
	// PackageMembers holds the legacy name-only selection index across every
	// file in this file's package. It is populated by the runner for callers
	// that need the historical name-only query.
	PackageMembers map[string]bool
	// PackageMemberSelections holds type-qualified member selections across
	// every file in this file's package. It is populated by the runner after
	// parsing, enabling cross-file unused member analysis without collisions
	// between unrelated types.
	PackageMemberSelections map[MemberKey]bool
}

type fileAnalysisCache struct {
	selectedMembersOnce sync.Once
	selectedMembers     map[string]bool
	selectedMemberUses  map[MemberKey]bool
	ifaceMethodsOnce    sync.Once
	ifaceMethods        map[string]bool
	ifaceMethodSigs     map[string][]*Function
	effectiveLOCOnce    sync.Once
	effectiveLOC        *metrics.EffectiveLOCIndex
}

// SelectedMemberNames returns a snapshot of field or method names selected or
// used in struct literals anywhere in this file.
func (f *File) SelectedMemberNames() map[string]bool {
	f.collectSelectedMemberNames()
	return maps.Clone(f.analysis.selectedMembers)
}

// PackageMemberNames returns a snapshot of field or method names selected
// anywhere across this file's package (or this file if analyzed in isolation).
func (f *File) PackageMemberNames() map[string]bool {
	if f.PackageMembers != nil {
		return maps.Clone(f.PackageMembers)
	}
	return f.SelectedMemberNames()
}

// MemberSelected reports whether name is selected or used in a struct literal
// anywhere in this file (or in this file's package if PackageMembers is
// populated). The file-wide AST scan runs once.
func (f *File) MemberSelected(name string) bool {
	if f.PackageMembers != nil {
		return f.PackageMembers[name]
	}
	f.collectSelectedMemberNames()
	return f.analysis.selectedMembers[name]
}

// MemberSelectedForType reports whether name is selected on typeName anywhere
// in this file (or in this file's package when package selections are set).
func (f *File) MemberSelectedForType(typeName, name string) bool {
	key := MemberKey{Type: typeName, Name: name}
	if f.PackageMemberSelections != nil {
		return f.PackageMemberSelections[key]
	}
	f.collectSelectedMemberNames()
	return f.analysis.selectedMemberUses[key]
}

// SelectedMemberUses returns type-qualified member selections for a file.
func SelectedMemberUses(f *File) map[MemberKey]bool {
	f.collectSelectedMemberNames()
	return maps.Clone(f.analysis.selectedMemberUses)
}

func (f *File) collectSelectedMemberNames() {
	f.analysis.selectedMembersOnce.Do(func() {
		f.analysis.selectedMembers, f.analysis.selectedMemberUses = collectSelectedMemberUses(f)
	})
}

// InterfaceMethodNames returns the set of method names declared by any
// interface in this file's package (or this file if analyzed in isolation),
// including methods inherited through embedded interfaces resolved within the
// same package. The set is computed at most once per file.
func (f *File) InterfaceMethodNames() map[string]bool {
	f.collectInterfaceMethods()
	return f.analysis.ifaceMethods
}

// collectInterfaceMethods builds, at most once per file, the set of method
// names declared by any interface in this file's package, plus the declared
// methods grouped by name for signature matching.
func (f *File) collectInterfaceMethods() {
	f.analysis.ifaceMethodsOnce.Do(func() {
		ifaces := f.Interfaces
		if f.PackageInterfaces != nil {
			ifaces = f.PackageInterfaces
		}
		byName := make(map[string]*Interface, len(ifaces))
		for _, i := range ifaces {
			byName[i.Name] = i
		}
		visited := map[string]bool{}
		names := map[string]bool{}
		sigs := map[string][]*Function{}
		var visit func(i *Interface)
		visit = func(i *Interface) {
			if visited[i.Name] {
				return
			}
			visited[i.Name] = true
			for _, m := range i.Methods {
				names[m.Name] = true
				sigs[m.Name] = append(sigs[m.Name], m)
			}
			for _, e := range i.Embeds {
				if emb := byName[e]; emb != nil {
					visit(emb)
				}
			}
		}
		for _, i := range ifaces {
			visit(i)
		}
		f.analysis.ifaceMethods = names
		f.analysis.ifaceMethodSigs = sigs
	})
}

// InterfaceMethodSatisfied reports whether fn (a concrete method) matches a
// same-named method declared by some interface in this file's package (or this
// file if analyzed in isolation), i.e. the method could satisfy that
// interface's method set. Matching requires identical parameter and result
// types, in order; a method whose signature differs from every same-named
// interface method satisfies nothing. Computed at most once per file.
func (f *File) InterfaceMethodSatisfied(fn *Function) bool {
	f.collectInterfaceMethods()
	for _, im := range f.analysis.ifaceMethodSigs[fn.Name] {
		if sameSignature(im, fn) {
			return true
		}
	}
	return false
}

func sameSignature(a, b *Function) bool {
	if len(a.Params) != len(b.Params) || len(a.Results) != len(b.Results) {
		return false
	}
	for i := range a.Params {
		if a.Params[i].Type != b.Params[i].Type {
			return false
		}
	}
	for i := range a.Results {
		if a.Results[i].Type != b.Results[i].Type {
			return false
		}
	}
	return true
}

// EffectiveLinesOfCode returns the number of code-bearing physical source
// lines in the requested span. The source is indexed at most once per file.
func (f *File) EffectiveLinesOfCode(start, end token.Pos) int {
	f.analysis.effectiveLOCOnce.Do(func() {
		f.analysis.effectiveLOC = metrics.NewEffectiveLOCIndex(f.Src)
	})
	return f.analysis.effectiveLOC.LinesOfCode(f.Fset, start, end)
}

// Parameter is a formal parameter of a function or method.
type Parameter struct {
	Name     string
	Type     string
	Line     int
	Field    *ast.Field
	Ident    *ast.Ident
	Promoted bool // reserved; Go has no constructor promotion
}

// Field is a struct field (the analog of a PHP class property).
type Field struct {
	Name     string
	Type     string
	TypeExpr ast.Expr
	Line     int
	Exported bool
	Static   bool // package-level var attached as a "static" field (unused for structs)
	Ident    *ast.Ident
}

// Function represents a free function OR a method (when Receiver != "").
// PHPMD distinguishes ASTMethod from ASTFunction; we keep one struct and use
// IsMethod()/Receiver to tell them apart, which keeps rule code uniform.
type Function struct {
	Name       string
	Receiver   string // empty for free functions; type name (without *) for methods
	RecvName   string // receiver variable name, e.g. "f" in (f *Foo)
	Params     []*Parameter
	Results    []*Parameter
	Line       int
	EndLine    int
	Exported   bool
	Decl       *ast.FuncDecl
	Body       *ast.BlockStmt
	File       *File
	Class      *Class // owning class for a method, if resolved
	DocComment string

	identifierReads identifierReadCache
}

func (f *Function) IsMethod() bool { return f.Receiver != "" }

type identifierReadCache struct {
	once       sync.Once
	names      map[string]bool
	objects    map[*ast.Object]bool
	unresolved map[string]bool
}

func functionIdentifierReadFacts(f *Function) *identifierReadCache {
	cache := &f.identifierReads
	cache.once.Do(func() {
		facts := scanIdentifierReads(f.Body)
		cache.names = facts.names
		cache.objects = facts.objects
		cache.unresolved = facts.unresolved
	})
	return cache
}

func (f *Function) NodeType() NodeType {
	if f.IsMethod() {
		return TypeMethod
	}
	return TypeFunction
}

// Class is a named struct type plus its associated methods (analog of a PHP
// class). A type defined as `type T struct{...}` becomes a Class; methods with
// receiver T are attached.
type Class struct {
	Name       string
	Line       int
	EndLine    int
	Exported   bool
	Fields     []*Field
	Methods    []*Function
	File       *File
	Spec       *ast.TypeSpec
	Struct     *ast.StructType
	DocComment string
	// Embeds holds embedded type names (the closest Go analog to parents).
	Embeds []string
}

func (c *Class) NodeType() NodeType { return TypeClass }

// Interface is a named interface type (analog of a PHP interface).
type Interface struct {
	Name       string
	Line       int
	EndLine    int
	Exported   bool
	Methods    []*Function
	File       *File
	Spec       *ast.TypeSpec
	Iface      *ast.InterfaceType
	DocComment string
	Embeds     []string
}

func (i *Interface) NodeType() NodeType { return TypeInterface }

sources.internal/model/promoted.go:
package model

import (
	"strings"
)

// PromotedMembers returns the names of all promoted fields and promoted methods
// reachable through this class's embedded structs and interfaces within the same package.
func (c *Class) PromotedMembers() (map[string]bool, map[string]bool) {
	if c == nil || len(c.Embeds) == 0 || c.File == nil {
		return map[string]bool{}, map[string]bool{}
	}
	collector := newPromotedMemberCollector(c)
	return collector.collect(c.Embeds)
}

type promotedMemberCollector struct {
	classByName     map[string]*Class
	ifaceByName     map[string]*Interface
	directFields    map[string]bool
	directMethods   map[string]bool
	promotedFields  map[string]bool
	promotedMethods map[string]bool
	visited         map[string]bool
}

func newPromotedMemberCollector(c *Class) *promotedMemberCollector {
	classByName, ifaceByName := c.packageTypeIndexes()
	return &promotedMemberCollector{
		classByName:     classByName,
		ifaceByName:     ifaceByName,
		directFields:    directFieldSet(c.Fields),
		directMethods:   directMethodSet(c.Methods),
		promotedFields:  map[string]bool{},
		promotedMethods: map[string]bool{},
		visited:         map[string]bool{c.Name: true},
	}
}

func (c *promotedMemberCollector) collect(embeds []string) (map[string]bool, map[string]bool) {
	var classQueue []*Class
	var ifaceQueue []*Interface
	for _, embedName := range embeds {
		c.tryEnqueueClass(embedName, &classQueue, &ifaceQueue)
	}
	c.processClassQueue(classQueue, &ifaceQueue)
	c.processIfaceQueue(ifaceQueue)
	return c.promotedFields, c.promotedMethods
}

func (c *promotedMemberCollector) addField(name string) {
	if !c.directFields[name] && !c.directMethods[name] && !c.promotedFields[name] {
		c.promotedFields[name] = true
	}
}

func (c *promotedMemberCollector) addMethod(name string) {
	if !c.directMethods[name] && !c.directFields[name] && !c.promotedMethods[name] {
		c.promotedMethods[name] = true
	}
}

func (c *promotedMemberCollector) addClassMembers(curr *Class) {
	for _, f := range curr.Fields {
		c.addField(f.Name)
	}
	for _, m := range curr.Methods {
		c.addMethod(m.Name)
	}
}

func (c *promotedMemberCollector) addIfaceMembers(curr *Interface) {
	for _, m := range curr.Methods {
		c.addMethod(m.Name)
	}
}

func (c *promotedMemberCollector) tryEnqueueClass(name string, classQueue *[]*Class, ifaceQueue *[]*Interface) {
	clean := cleanEmbedName(name)
	if clean == "" || c.visited[clean] {
		return
	}
	c.visited[clean] = true
	if embClass := c.classByName[clean]; embClass != nil {
		*classQueue = append(*classQueue, embClass)
		return
	}
	if embIface := c.ifaceByName[clean]; embIface != nil {
		*ifaceQueue = append(*ifaceQueue, embIface)
	}
}

func (c *promotedMemberCollector) tryEnqueueIface(name string, queue *[]*Interface) {
	clean := cleanEmbedName(name)
	if clean == "" || c.visited[clean] {
		return
	}
	c.visited[clean] = true
	if embIface := c.ifaceByName[clean]; embIface != nil {
		*queue = append(*queue, embIface)
	}
}

func (c *promotedMemberCollector) processClassQueue(queue []*Class, ifaceQueue *[]*Interface) {
	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]
		c.addClassMembers(curr)
		for _, embedName := range curr.Embeds {
			c.tryEnqueueClass(embedName, &queue, ifaceQueue)
		}
	}
}

func (c *promotedMemberCollector) processIfaceQueue(queue []*Interface) {
	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]
		c.addIfaceMembers(curr)
		for _, embedName := range curr.Embeds {
			c.tryEnqueueIface(embedName, &queue)
		}
	}
}

func (c *Class) packageTypeIndexes() (map[string]*Class, map[string]*Interface) {
	classes := c.File.PackageClasses
	if classes == nil {
		classes = c.File.Classes
	}
	classByName := make(map[string]*Class, len(classes))
	for _, cls := range classes {
		classByName[cls.Name] = cls
	}
	ifaces := c.File.PackageInterfaces
	if ifaces == nil {
		ifaces = c.File.Interfaces
	}
	ifaceByName := make(map[string]*Interface, len(ifaces))
	for _, iface := range ifaces {
		ifaceByName[iface.Name] = iface
	}
	return classByName, ifaceByName
}

func directFieldSet(fields []*Field) map[string]bool {
	set := make(map[string]bool, len(fields))
	for _, f := range fields {
		set[f.Name] = true
	}
	return set
}

func directMethodSet(methods []*Function) map[string]bool {
	set := make(map[string]bool, len(methods))
	for _, m := range methods {
		set[m.Name] = true
	}
	return set
}

func cleanEmbedName(name string) string {
	clean := strings.TrimPrefix(name, "*")
	if strings.Contains(clean, ".") {
		return ""
	}
	return clean
}

sources.internal/model/query.go:
package model

import (
	"go/ast"
	"go/constant"
	"go/token"
	"maps"
	"path"
	"strconv"

	"github.com/quality-gates/messgo/internal/util"
)

// Call describes a function call found inside an artifact.
type Call struct {
	Name        string
	Selector    string
	PackagePath string
	Line        int
}

// SourcePosition identifies a position in the original source file.
type SourcePosition struct {
	Line   int
	Column int
}

// DuplicateLiteralKey describes a repeated constant key in a composite literal.
type DuplicateLiteralKey struct {
	Display   string
	FirstLine int
	Line      int
}

// PackageVar describes a package-level variable declaration.
type PackageVar struct {
	Name string
	Line int
}

// LocalVariable describes a local variable declaration.
type LocalVariable struct {
	Name   string
	Line   int
	IsLoop bool
	Ident  *ast.Ident
}

// HasGoto reports whether the function body contains a goto statement.
func HasGoto(f *Function) bool {
	if f.Body == nil {
		return false
	}
	found := false
	ast.Inspect(f.Body, func(n ast.Node) bool {
		if b, ok := n.(*ast.BranchStmt); ok && b.Tok == token.GOTO {
			found = true
			return false
		}
		return true
	})
	return found
}

// Calls returns every call expression in this function body.
func Calls(f *Function) []Call {
	if f == nil || f.Body == nil {
		return nil
	}
	var out []Call
	ast.Inspect(f.Body, func(n ast.Node) bool {
		if ce, ok := n.(*ast.CallExpr); ok {
			out = append(out, callDetails(f.File, ce))
		}
		return true
	})
	return out
}

func callDetails(file *File, ce *ast.CallExpr) Call {
	call := Call{Name: calleeName(ce.Fun), Line: file.Fset.Position(ce.Pos()).Line}
	if selector, ok := calledSelector(ce.Fun); ok {
		call.Selector = selector.Sel.Name
		call.PackagePath = importedPackagePath(file, packageQualifier(selector.X))
	}
	return call
}

func calledSelector(expr ast.Expr) (*ast.SelectorExpr, bool) {
	for {
		switch node := expr.(type) {
		case *ast.ParenExpr:
			expr = node.X
		case *ast.SelectorExpr:
			return node, true
		default:
			return nil, false
		}
	}
}

func packageQualifier(expr ast.Expr) *ast.Ident {
	for {
		switch node := expr.(type) {
		case *ast.ParenExpr:
			expr = node.X
		case *ast.Ident:
			return node
		default:
			return nil
		}
	}
}

func importedPackagePath(file *File, qualifier *ast.Ident) string {
	if !resolvableImportQualifier(file, qualifier) {
		return ""
	}
	for _, spec := range file.Syntax.Imports {
		importPath, ok := importPath(spec)
		if !ok {
			continue
		}
		if !importMatchesQualifier(spec, importPath, qualifier.Name) {
			continue
		}
		return importPath
	}
	return ""
}

func resolvableImportQualifier(file *File, qualifier *ast.Ident) bool {
	return file != nil && file.Syntax != nil && qualifier != nil && qualifier.Obj == nil
}

func importMatchesQualifier(spec *ast.ImportSpec, importPath, qualifierName string) bool {
	localName := path.Base(importPath)
	if spec.Name != nil {
		localName = spec.Name.Name
	}
	return localName != "_" && localName != "." && localName == qualifierName
}

func importPath(spec *ast.ImportSpec) (string, bool) {
	if spec == nil || spec.Path == nil {
		return "", false
	}
	value, err := strconv.Unquote(spec.Path.Value)
	if err != nil {
		return "", false
	}
	return value, true
}

// LoopConditionCalls returns calls to selected names found in for-loop
// conditions, reported at the loop's line.
func LoopConditionCalls(f *Function, names map[string]bool) []Call {
	if f == nil || f.Body == nil {
		return nil
	}
	var out []Call
	ast.Inspect(f.Body, func(n ast.Node) bool {
		fs, ok := n.(*ast.ForStmt)
		if !ok || fs.Cond == nil {
			return true
		}
		ast.Inspect(fs.Cond, func(cn ast.Node) bool {
			ce, ok := cn.(*ast.CallExpr)
			if !ok {
				return true
			}
			name := calleeName(ce.Fun)
			if names[name] {
				out = append(out, Call{Name: name, Line: f.File.Fset.Position(fs.Pos()).Line})
			}
			return true
		})
		return true
	})
	return out
}

// EmptyNilCheckBlockLines returns lines for empty if-blocks whose condition
// compares any operand with nil using !=.
func EmptyNilCheckBlockLines(f *Function) []int {
	if f == nil || f.Body == nil {
		return nil
	}
	var lines []int
	ast.Inspect(f.Body, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Body == nil || len(ifs.Body.List) != 0 {
			return true
		}
		if conditionChecksNil(ifs.Cond) {
			lines = append(lines, f.File.Fset.Position(ifs.Pos()).Line)
		}
		return true
	})
	return lines
}

// ElseBlockLines returns the source lines of else blocks, excluding else-if
// chains.
func ElseBlockLines(f *Function) []int {
	if f == nil || f.Body == nil {
		return nil
	}
	var lines []int
	ast.Inspect(f.Body, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if _, isBlock := ifs.Else.(*ast.BlockStmt); isBlock {
			lines = append(lines, f.File.Fset.Position(ifs.Else.Pos()).Line)
		}
		return true
	})
	return lines
}

// IfAssignmentInitPositions returns positions for plain assignment initializers
// in if statements. Short declarations are intentionally excluded.
func IfAssignmentInitPositions(f *Function) []SourcePosition {
	if f == nil || f.Body == nil {
		return nil
	}
	var positions []SourcePosition
	ast.Inspect(f.Body, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		assign, ok := ifs.Init.(*ast.AssignStmt)
		if ok && assign.Tok == token.ASSIGN {
			pos := f.File.Fset.Position(assign.Pos())
			positions = append(positions, SourcePosition{Line: pos.Line, Column: pos.Column})
		}
		return true
	})
	return positions
}

// DuplicateLiteralKeys returns duplicate constant keys in composite literals.
func DuplicateLiteralKeys(f *Function) []DuplicateLiteralKey {
	if f == nil || f.Body == nil {
		return nil
	}
	return duplicateLiteralKeys(f.Body, f.File.Fset)
}

// PackageDuplicateLiteralKeys returns duplicate constant keys in package-level
// composite literals.
func (f *File) PackageDuplicateLiteralKeys() []DuplicateLiteralKey {
	var out []DuplicateLiteralKey
	for _, decl := range f.Syntax.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		out = append(out, duplicateLiteralKeys(gd, f.Fset)...)
	}
	return out
}

func duplicateLiteralKeys(root ast.Node, fset *token.FileSet) []DuplicateLiteralKey {
	var out []DuplicateLiteralKey
	ast.Inspect(root, func(n ast.Node) bool {
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		out = append(out, duplicateKeysInLiteral(cl, fset)...)
		return true
	})
	return out
}

func duplicateKeysInLiteral(cl *ast.CompositeLit, fset *token.FileSet) []DuplicateLiteralKey {
	var out []DuplicateLiteralKey
	seen := map[string]int{}
	for _, elt := range cl.Elts {
		kv, ok := elt.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key, ok := literalKey(kv.Key)
		if !ok {
			continue
		}
		line := fset.Position(kv.Key.Pos()).Line
		if first, dup := seen[key]; dup {
			out = append(out, DuplicateLiteralKey{
				Display:   displayKey(kv.Key),
				FirstLine: first,
				Line:      line,
			})
			continue
		}
		seen[key] = line
	}
	return out
}

// PackageVars returns package-level variables declared in the file, skipping
// the blank identifier.
func (f *File) PackageVars() []PackageVar {
	var out []PackageVar
	for _, decl := range f.Syntax.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.VAR {
			continue
		}
		for _, spec := range gd.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for _, name := range vs.Names {
				if name.Name == "_" {
					continue
				}
				out = append(out, PackageVar{Name: name.Name, Line: f.Fset.Position(name.Pos()).Line})
			}
		}
	}
	return out
}

// MutatedPackageGlobals returns package-level variable names mutated in this
// file unless the runner has already populated cross-file mutation data.
func (f *File) MutatedPackageGlobals() map[string]bool {
	if f.MutatedGlobals != nil {
		return f.MutatedGlobals
	}
	return util.MutatedGlobalNames([]*ast.File{f.Syntax})
}

// LocalVariables returns local variable declarations in this function.
func LocalVariables(f *Function) []LocalVariable {
	if f == nil || f.Body == nil {
		return nil
	}
	locals := util.LocalVariables(f.Body, f.File.Fset)
	out := make([]LocalVariable, 0, len(locals))
	for _, v := range locals {
		out = append(out, LocalVariable{Name: v.Name, Line: v.Line, IsLoop: v.IsLoop, Ident: v.Ident})
	}
	return out
}

// IdentifierReads returns names read from this function body. Identifiers used
// only as assignment or declaration write targets are excluded.
func IdentifierReads(f *Function) map[string]bool {
	if f == nil {
		return nil
	}
	return maps.Clone(functionIdentifierReadFacts(f).names)
}

// IdentifierRead reports whether target's binding is read in this function.
// Object identity distinguishes a shadowing local from a captured parameter or
// local with the same name.
func IdentifierRead(f *Function, target *ast.Ident) bool {
	if f.Body == nil || target == nil {
		return false
	}
	facts := functionIdentifierReadFacts(f)
	if target.Obj != nil {
		return facts.objects[target.Obj]
	}
	return facts.unresolved[target.Name]
}

type identifierReadFacts struct {
	names       map[string]bool
	objects     map[*ast.Object]bool
	unresolved  map[string]bool
	writes      map[*ast.Ident]bool
	objectDepth map[*ast.Object]int
}

type identifierReadVisitor struct {
	facts *identifierReadFacts
	depth int
}

func scanIdentifierReads(body *ast.BlockStmt) identifierReadFacts {
	facts := identifierReadFacts{
		names:       map[string]bool{},
		objects:     map[*ast.Object]bool{},
		unresolved:  map[string]bool{},
		writes:      map[*ast.Ident]bool{},
		objectDepth: map[*ast.Object]int{},
	}
	if body != nil {
		ast.Walk(identifierReadVisitor{facts: &facts}, body)
	}
	return facts
}

func (v identifierReadVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}
	depth := v.depth
	if literal, ok := node.(*ast.FuncLit); ok {
		depth++
		collectFieldObjectDepth(literal.Type.Params, depth, v.facts.objectDepth)
		collectFieldObjectDepth(literal.Type.Results, depth, v.facts.objectDepth)
	}
	collectDeclaredObjectDepth(node, depth, v.facts.objectDepth)
	collectNodeWrites(node, v.facts.writes)
	if id, ok := node.(*ast.Ident); ok {
		v.facts.recordRead(id)
	}
	return identifierReadVisitor{facts: v.facts, depth: depth}
}

func (f *identifierReadFacts) recordRead(id *ast.Ident) {
	if !isReadIdentifier(id, f.writes) {
		return
	}
	if id.Obj == nil {
		f.unresolved[id.Name] = true
		f.names[id.Name] = true
		return
	}
	f.objects[id.Obj] = true
	if f.objectDepth[id.Obj] == 0 {
		f.names[id.Name] = true
	}
}

func collectNodeWrites(node ast.Node, writes map[*ast.Ident]bool) {
	switch declaration := node.(type) {
	case *ast.AssignStmt:
		collectAssignWrites(declaration, writes)
	case *ast.ValueSpec:
		for _, id := range declaration.Names {
			writes[id] = true
		}
	case *ast.RangeStmt:
		collectRangeWrites(declaration, writes)
	}
}

func collectDeclaredObjectDepth(node ast.Node, depth int, objectDepth map[*ast.Object]int) {
	switch declaration := node.(type) {
	case *ast.ValueSpec:
		collectIdentObjectDepth(declaration.Names, depth, objectDepth)
	case *ast.AssignStmt:
		collectShortObjectDepth(declaration, depth, objectDepth)
	case *ast.RangeStmt:
		collectRangeObjectDepth(declaration, depth, objectDepth)
	case *ast.TypeSpec:
		setObjectDepth(declaration.Name, depth, objectDepth)
	}
}

func collectFieldObjectDepth(fields *ast.FieldList, depth int, objectDepth map[*ast.Object]int) {
	if fields == nil {
		return
	}
	for _, field := range fields.List {
		collectIdentObjectDepth(field.Names, depth, objectDepth)
	}
}

func collectIdentObjectDepth(idents []*ast.Ident, depth int, objectDepth map[*ast.Object]int) {
	for _, id := range idents {
		setObjectDepth(id, depth, objectDepth)
	}
}

func setObjectDepth(id *ast.Ident, depth int, objectDepth map[*ast.Object]int) {
	if id != nil && id.Obj != nil {
		objectDepth[id.Obj] = depth
	}
}

func collectShortObjectDepth(assign *ast.AssignStmt, depth int, objectDepth map[*ast.Object]int) {
	if assign.Tok != token.DEFINE {
		return
	}
	for _, lhs := range assign.Lhs {
		id, ok := lhs.(*ast.Ident)
		if ok && isDeclaredBy(id, assign) {
			setObjectDepth(id, depth, objectDepth)
		}
	}
}

func collectRangeObjectDepth(rng *ast.RangeStmt, depth int, objectDepth map[*ast.Object]int) {
	if rng.Tok != token.DEFINE {
		return
	}
	for _, expr := range []ast.Expr{rng.Key, rng.Value} {
		id, ok := expr.(*ast.Ident)
		if ok && isRangeDeclaredBy(id, rng) {
			setObjectDepth(id, depth, objectDepth)
		}
	}
}

func isReadIdentifier(id *ast.Ident, writeIdents map[*ast.Ident]bool) bool {
	return id.Name != "_" && !writeIdents[id]
}

func isDeclaredBy(id *ast.Ident, decl ast.Node) bool {
	return util.DeclaredBy(id, decl)
}

func isRangeDeclaredBy(id *ast.Ident, decl *ast.RangeStmt) bool {
	if !rangeDeclHasIdentifier(id, decl) {
		return false
	}
	assign, ok := id.Obj.Decl.(*ast.AssignStmt)
	if !ok || assign.Tok != token.DEFINE {
		return false
	}
	return assignmentContainsIdent(assign, id)
}

func rangeDeclHasIdentifier(id *ast.Ident, decl *ast.RangeStmt) bool {
	if id == nil || id.Obj == nil {
		return false
	}
	if decl == nil || decl.Tok != token.DEFINE {
		return false
	}
	return id == decl.Key || id == decl.Value
}

func assignmentContainsIdent(assign *ast.AssignStmt, id *ast.Ident) bool {
	for _, lhs := range assign.Lhs {
		if lhs == id {
			return true
		}
	}
	return false
}

func collectAssignWrites(s *ast.AssignStmt, writeIdents map[*ast.Ident]bool) {
	if s.Tok == token.ASSIGN || s.Tok == token.DEFINE {
		for _, lhs := range s.Lhs {
			if id, ok := lhs.(*ast.Ident); ok {
				writeIdents[id] = true
			}
		}
	}
}

func collectRangeWrites(s *ast.RangeStmt, writeIdents map[*ast.Ident]bool) {
	if s.Tok == token.ASSIGN || s.Tok == token.DEFINE {
		if id, ok := s.Key.(*ast.Ident); ok {
			writeIdents[id] = true
		}
		if id, ok := s.Value.(*ast.Ident); ok {
			writeIdents[id] = true
		}
	}
}

// AccessorField returns the field wrapped by a trivial getter or setter.
func AccessorField(f *Function, fields map[string]bool) string {
	if f.Body == nil || len(f.Body.List) != 1 {
		return ""
	}
	switch stmt := f.Body.List[0].(type) {
	case *ast.ReturnStmt:
		return returnAccessorField(stmt, f.RecvName, fields)
	case *ast.AssignStmt:
		return assignAccessorField(stmt, f.RecvName, fields)
	}
	return ""
}

func returnAccessorField(stmt *ast.ReturnStmt, recvName string, fields map[string]bool) string {
	if len(stmt.Results) != 1 {
		return ""
	}
	return receiverFieldSelector(stmt.Results[0], recvName, fields)
}

func assignAccessorField(stmt *ast.AssignStmt, recvName string, fields map[string]bool) string {
	if stmt.Tok != token.ASSIGN || len(stmt.Lhs) != 1 || len(stmt.Rhs) != 1 {
		return ""
	}
	if !isPlainValue(stmt.Rhs[0]) {
		return ""
	}
	return receiverFieldSelector(stmt.Lhs[0], recvName, fields)
}

// ReceiverUses returns fields and sibling methods selected through the
// receiver variable in this function body.
func ReceiverUses(f *Function, fields map[string]bool, methods map[string]int) (usedFields, calledMethods []string) {
	if f.Body == nil || f.RecvName == "" || f.RecvName == "_" {
		return nil, nil
	}
	seen := map[string]bool{}
	ast.Inspect(f.Body, func(n ast.Node) bool {
		name := receiverSelector(n, f.RecvName)
		if name == "" || seen[name] {
			return true
		}
		_, isMethod := methods[name]
		switch {
		case fields[name]:
			seen[name] = true
			usedFields = append(usedFields, name)
		case isMethod:
			seen[name] = true
			calledMethods = append(calledMethods, name)
		}
		return true
	})
	return usedFields, calledMethods
}

func isPlainValue(e ast.Expr) bool {
	switch e.(type) {
	case *ast.Ident, *ast.BasicLit:
		return true
	}
	return false
}

func receiverFieldSelector(e ast.Expr, recvName string, fields map[string]bool) string {
	sel, ok := e.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if ok && id.Name == recvName && fields[sel.Sel.Name] {
		return sel.Sel.Name
	}
	return ""
}

func receiverSelector(n ast.Node, recvName string) string {
	sel, ok := n.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	id, ok := sel.X.(*ast.Ident)
	if !ok || id.Name != recvName {
		return ""
	}
	return sel.Sel.Name
}

func conditionChecksNil(cond ast.Expr) bool {
	found := false
	ast.Inspect(cond, func(n ast.Node) bool {
		be, ok := n.(*ast.BinaryExpr)
		if !ok || be.Op != token.NEQ {
			return true
		}
		if isNilIdent(be.X) || isNilIdent(be.Y) {
			found = true
		}
		return true
	})
	return found
}

func isNilIdent(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && id.Name == "nil"
}

func literalKey(e ast.Expr) (string, bool) {
	switch k := e.(type) {
	case *ast.ParenExpr:
		return literalKey(k.X)
	case *ast.UnaryExpr:
		return unaryLitKey(k)
	case *ast.BasicLit:
		return basicLitKey(k.Value, k.Kind)
	case *ast.Ident:
		return "ident:" + k.Name, true
	}
	return "", false
}

func basicLitKey(val string, kind token.Token) (string, bool) {
	v := constant.MakeFromLiteral(val, kind, 0)
	if v.Kind() == constant.Unknown {
		return kind.String() + ":" + val, true
	}
	return v.Kind().String() + ":" + v.ExactString(), true
}

func unaryLitKey(u *ast.UnaryExpr) (string, bool) {
	if u.Op != token.SUB && u.Op != token.ADD {
		return "", false
	}
	lit, ok := u.X.(*ast.BasicLit)
	if !ok {
		return "", false
	}
	return basicLitKey(u.Op.String()+lit.Value, lit.Kind)
}

func displayKey(e ast.Expr) string {
	switch k := e.(type) {
	case *ast.ParenExpr:
		return displayKey(k.X)
	case *ast.UnaryExpr:
		if k.Op == token.SUB || k.Op == token.ADD {
			return k.Op.String() + displayKey(k.X)
		}
	case *ast.BasicLit:
		return k.Value
	case *ast.Ident:
		return k.Name
	}
	return ""
}

func calleeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		x := calleeName(t.X)
		if x == "" {
			return t.Sel.Name
		}
		return x + "." + t.Sel.Name
	case *ast.ParenExpr:
		return calleeName(t.X)
	default:
		return ""
	}
}

